import sys
import csv
import json


def main():
    path = sys.argv[1]
    merges = {}
    with open(path, 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print(json.dumps([], ensure_ascii=False))
            return
        cols = [h.strip().casefold() for h in header]
        try:
            item_idx = cols.index('item')
            qty_idx = cols.index('quantity')
        except ValueError:
            item_idx, qty_idx = 0, 1

        for row in reader:
            if len(row) <= item_idx or len(row) <= qty_idx:
                continue
            item_raw = row[item_idx]
            qty_raw = row[qty_idx]

            item_norm = ' '.join(item_raw.split()).casefold()
            if not item_norm:
                continue

            q_str = qty_raw.strip()
            if q_str == '':
                qty = 1
            else:
                qty = int(q_str, 10)

            merges[item_norm] = merges.get(item_norm, 0) + qty

    result = [{"item": k, "quantity": merges[k]} for k in sorted(merges.keys())]
    print(json.dumps(result, ensure_ascii=False))


if __name__ == '__main__':
    main()
